import Link from "next/link";
import type {ReactNode} from "react";
import {CopyButton} from "./primitives";
import {NetworkStrip} from "./public";
import {docsSections,type DocsSection} from "../app/docs/sections";
function Toc({section}:{section:DocsSection}){let group="";return <nav aria-label="Documentation contents">{docsSections.map(([g,id,label])=>{const changed=group!==g;group=g;return <span key={id}>{changed?<span className="toc-group">{g}</span>:null}<Link href={"/docs/"+id} aria-current={section===id?"page":undefined} className={section===id?"docs-section-current":undefined}>{label}</Link></span>})}</nav>}
function Code({title,children}:{title:string;children:string}){return <div className="code-block"><div className="code-caption"><span>{title}</span><CopyButton value={children} label={"Copy "+title}/></div><pre><code>{children}</code></pre></div>}
function Table({heads,rows}:{heads:string[];rows:string[][]}){return <div className="table-wrap"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{c}</td>)}</tr>)}</tbody></table></div>}

const content:Record<DocsSection,ReactNode>={
"quickstart":<section id="quickstart"><h2>Quickstart</h2><p>IntentGuard gives one agent access to one owner-funded spending vault. The key can request payments; the owner decides the mission, recipients and immutable financial limits. The budget guard and finalized evidence review must both allow a purchase before settlement.</p><ol><li>Start with the public explorer to inspect a paid or blocked record without a wallet. For setup, connect your owner wallet and confirm the payment environment advertised by the service before signing.</li><li>Open Create agent. Enter identity, purchase permissions, approved merchants, evidence criteria, budgets and UTC validity.</li><li>Propose the policy. Keep the draft URL while the Actions worker obtains a GenLayer Studionet proposal and finalized consensus.</li><li>Read every proposed term. If clarification is required, revise the instructions. Activate only a successful finalized proposal you approve.</li><li>Select a release-verified asset and approve its spending networks. USDC supports local and selected CCTP routes; mainnet USDT0 settles on X Layer only. Fund the actual vault token, then wait for reviewer initialization.</li><li>Issue the agent’s API key, save it once and submit an invoice-backed payment with an Idempotency-Key.</li><li>Poll the same request ID. PAID means delivery completed. APPROVED and CCTP bridge states remain pending until destination receipt and vault acknowledgement are verified.</li></ol><p>The existing testnet uses chain 1952; its native USDC and legacy TEST-USDT have no monetary value. The separate mainnet beta uses chain 196, with USDC and local USDT0 only after deployment verification. Both use GenLayer Studionet 61999 testnet review. An unverified environment disables owner actions. GitHub runner availability and review finality introduce minute-scale latency.</p></section>,
"wallet-sessions":<section id="wallet-sessions"><h2>Wallet and session authentication</h2><p>The browser requests an owner address, receives a single-use login challenge and asks the wallet to sign that exact message. The API verifies the signature. A same-origin application uses an HttpOnly cookie; a separate approved frontend uses a short-lived Owner bearer session held only in browser memory. Cross-origin login does not rely on third-party cookies. Agent API keys are separate from owner sessions.</p><p>The challenge binds the approved frontend, API origin, payment environment and chain. Use the same legitimate deployment through challenge and login. Cross-site origins, stale challenges, expired sessions and switched accounts cannot authorize owner writes. After changing accounts, sign in again.</p><p>Signing the login message does not transfer tokens. Activation, funding, pause, cancellation, revocation and withdrawal are wallet transactions. The app requests the advertised X Layer payment chain and can ask your wallet to add its configured RPC. Review each transaction in your wallet.</p><Code title="Owner session endpoints">{`POST /api/v1/auth/challenge
{"address":"<OWNER_EVM_ADDRESS>"}
POST /api/v1/auth/login
{"address":"<OWNER_EVM_ADDRESS>","signature":"<WALLET_SIGNATURE>"}
GET /api/v1/auth/session
POST /api/v1/auth/logout`}</Code><p>Declining a request leaves setup intact. Policy input is stored in this browser for the owner wallet; signatures and one-time keys are excluded. The setup URL’s draftId resumes a submitted proposal after refresh.</p><h3>Canonical URL and existing policies</h3><p>The application origin is now https://intentguard-tapeout.vercel.app. Existing immutable policies may approve evidence or merchant invoices on the previous application alias. That source origin remains compatible; changing the UI URL does not rewrite activated policies. New owners should explicitly select the origins they trust.</p></section>,
"policy-fields":<section id="policy-fields"><h2>Complete policy reference</h2><p>The structured policy is version 1. GenLayer proposes typed terms from your mission and guidance, and validators check fidelity to the original instructions. The owner chooses the agent name. Review the proposed terms because the activated policy cannot be edited.</p><h3>Identity and purchase scope</h3><Table heads={["Field","Meaning and constraints"]} rows={[["version","Exactly 1."],["name","Required owner-controlled agent name, 1–80 characters."],["mission","Task and purpose for which the agent may spend. Maximum 4,000 characters."],["taskContext","Deliverables, constraints and background. Maximum 6,000 characters; can be empty."],["allowedCategories","1–20 permitted categories, up to 200 characters each."],["prohibitedPurchases","Up to 20 explicit exclusions, 500 characters each. Empty adds no exclusions."],["exceptions","Up to 20 explicit exceptions, 500 characters each. They do not override onchain limits."]]}/><h3>Exact budgets and validity</h3><Table heads={["financial field","Enforcement"]} rows={[["totalBudget","Positive lifetime cumulative limit. Spending plus pending reservations consumes it."],["perPaymentLimit","Positive maximum per request; cannot exceed totalBudget."],["periodBudget","Positive maximum within each budget period, including reservations."],["periodSeconds","Integer 60–31,536,000. Time periods use seconds, not calendar months."],["validFrom","Nonnegative Unix timestamp in seconds. New requests are blocked before it."],["validUntil","Positive Unix timestamp after validFrom. Reservations and releases obey expiry."]]}/><p>Amounts are exact decimal strings with at most six fractional digits, converted to unsigned 64-bit atomic units. One USDC, USDT0 or legacy TEST-USDT is 1,000,000 units. Never construct money using floating point. A funded balance does not increase the lifetime budget.</p><p>Period reservations stay attached to the original period across rollover. At most two reservations can be outstanding. Available tokens, remaining lifetime budget and remaining period budget are separate values; all relevant checks must pass.</p><h3>Merchants, origins and products</h3><p>Each of 1–32 merchants has a name up to 100 characters, a unique EVM recipient, 1–10 HTTPS origins and up to 30 product descriptions of 200 characters each. Origins use public DNS HTTPS without credentials, paths, queries or fragments. Local, private and numeric IP destinations are invalid.</p><p>The vault enforces recipient addresses. Names, origins and products define semantic boundaries for the reviewer. Origins are not wildcards for unrelated hosts: explicitly approve every source.</p><h3>Evidence and review criteria</h3><Table heads={["Field","Meaning"]} rows={[["evidence.requiredTypes","1–10 proof types, each up to 200 characters."],["evidence.approvedOrigins","1–30 approved public HTTPS origins."],["evidence.maxAgeSeconds","Integer 1–31,536,000; maximum evidence freshness interval."],["criteria[].id","1–12 unique IDs of 1–40 letters, numbers, underscores or hyphens."],["criteria[].description","3–1,000 characters describing what to verify. Every criterion must PASS."]]}/><p>Setup captures every field above, including exclusions, exceptions, product restrictions, custom periods and freshness. Final review displays all clauses, merchants, budgets and dates as readable terms.</p></section>,
"proposal":<section id="proposal"><h2>Propose, review and activate</h2><p>Submitting mission and guidance creates an asynchronous draft. State describes processing; status describes the proposal result. FINALIZED plus PROPOSED is eligible for activation only with a verified activation configuration.</p><Code title="Draft submission">{`POST /api/v1/owner/drafts
{"description":"<OWNER_MISSION>","guidance":<COMPLETE_POLICY_JSON>,
 "settlement":{"asset":"USDC","destinationChainIds":[1952,84532,421614]}}
GET /api/v1/owner/drafts/<DRAFT_ID>
// Returns state, status, policy, questions, interpretation,
// genLayerTxHash and activation configuration.`}</Code><p>NEEDS_CLARIFICATION returns questions. Edit and submit a new proposal. Pending or failed drafts are not approved permissions. Terminal consensus or VM failures become FAILED with a clear error; edit and submit a new proposal. Setup polls every five seconds while online.</p><p>Review the chosen asset and spending-network subset as well as the policy. Destination permissions are stored outside interpreter guidance and committed at activation and reviewer initialization. Legacy USDC settlement uses reviewer V3; settlement version 2 requires V4. Include the configured source chain (1952 testnet or 196 mainnet) for direct X Layer payments. Omitted settlement preserves legacy drafts. Activation sends the exact finalized config to the selected factory through your wallet. The API verifies the confirmed CardCreated event and every immutable field before registration. The browser saves the public activation receipt for recovery; retry after interrupted registration verifies it instead of deploying another vault.</p><p>My agents selects the created vault after activation. Fund it and wait for reviewer initialization, then issue the credential. Revised terms require a new vault.</p></section>,
"funding":<section id="funding"><h2>Funding and reviewer initialization</h2><p>Activation creates permission but does not fund it. New cards hold one verified source asset: native Circle USDC on the selected X Layer environment, or USDT0 for local mainnet settlement. Fund vault transfers the selected card’s actual token from your owner wallet to its vault. Read <code>/me.card.token</code> or CardView first; <code>/config.token</code> is a compatibility field and must not be used to choose a USDC vault’s deposit token.</p><h3>Obtain testnet USDC and gas</h3><p>Use the <a href="https://faucet.circle.com" target="_blank" rel="noreferrer">Circle USDC faucet</a> or an existing native issuer-token balance. If the faucet only offers another supported testnet, use an official route and verify arrival on X Layer before depositing. The app never fabricates balances or calls a custom mint function on issuer USDC. Native test OKB is required for owner transaction gas; the <a href="https://web3.okx.com/xlayer/faucet/xlayerfaucet" target="_blank" rel="noreferrer">X Layer faucet</a> is the gas-funding entry.</p><Code title="Native X Layer USDC deposit">{`// Verify wallet chain 1952 and the selected card token.
const {card} = await ig.me();
await walletClient.writeContract({
  address: card.token,
  abi: erc20Abi,
  functionName: "transfer",
  args: [card.address, exactAtomicAmount]
});
// Check the successful token receipt and current card balance.`}</Code><p>USDC uses six decimals. Adding source tokens never enlarges the immutable lifetime, period or per-payment budgets. Choose your agent’s allowed destinations before activation; see <Link href="/docs/crosschain">USDC and cross-chain spending</Link>.</p><h3>Existing TEST-USDT agents</h3><p>Existing synthetic TEST-USDT vaults retain their original token and reviewer. Their public legacy faucet permits mint(address,uint256), at most 100,000 tokens per call, to the owner wallet before a separate vault transfer. The Mint legacy TEST-USDT control is available only for that configured token. Legacy cards cannot pay on another chain and are never relabeled USDC/USDT0. All testnet tokens have no monetary value.</p><h3>Reviewer readiness</h3><p>The Actions worker deploys and verifies a per-agent PurchaseReviewer. Legacy native-USDC reviewers use version 3. New settlement version 2 uses reviewer version 4, binding the source environment, asset, settlement hash and approved destination domains to Studionet testnet review. Existing version 1/2 source pins are preserved. API-key issuance waits for successful reviewer initialization; funding and reviewer readiness are independent.</p><p>A terminal initialization failure shows its actual error and Retry reviewer initialization in My agents. This owner-only retry preserves the same immutable vault/policy and creates a separate journaled reviewer attempt.</p><h3>Balances and spending capacity</h3><p>balances.funded is current source-vault token balance, not cumulative deposits. balances.available subtracts pending reservations. balances.spent counts direct payments and CCTP burns, even while destination delivery is pending. periodSpent/periodReserved track the current budget period; burned requests remain charged to their original reservation period.</p><p>Lifetime capacity is totalBudget − spent − reserved. Period capacity is periodBudget − periodSpent − periodReserved. A purchase must fit physical available funds, both capacities and perPaymentLimit. Downloaded card fundsMoved counts only PAID delivery and excludes pending burns.</p></section>,
"crosschain":<section id="crosschain"><h2>Native USDC and cross-chain spending</h2><p>The human deposits native USDC on the selected X Layer source chain. The agent pays only merchants and destinations in its immutable permission and the verified deployment capabilities. Legacy settlement supports X Layer Testnet, Base Sepolia and Arbitrum Sepolia. Settlement version 2 supports a verified subset of ten CCTP destinations plus local settlement; the mainnet and matching testnet profiles remain separate. Testnet tokens have no monetary value.</p><Table heads={["Spending network","EVM chain ID / CCTP domain","Native USDC"]} rows={[["X Layer Testnet","1952 / 37","0xDec90b78111Ba2fc6FC6d84d8B9ec159A2d4b9B3"],["Base Sepolia","84532 / 6","0x036CbD53842c5426634e7929541eC2318f3dCF7e"],["Arbitrum Sepolia","421614 / 3","0x75faf114eafb1BDbe2F0316DF893fd58CE46AA4d"]]}/><h3>Choose immutable permission</h3><p>At agent setup, choose USDC and a nonempty subset of spending networks. Include chain 1952 if direct X Layer payments are permitted. The owner reviews these destinations alongside the finalized policy before activating the CCTP vault. The API verifies the actual factory, token and allowed domains; the versioned reviewer verifies the settlement and destination commitment. Existing TEST-USDT agents keep their original single-chain token and source pins.</p><Code title="Asset and destination discovery">{`GET /api/v1/config
// assets, spendingNetworks, cctpFactoryAddress
GET /api/v1/me
// card.token, paymentSymbol, chainId, balances, settlement
settlement = {
  asset: "USDC",
  destinationChainIds: [1952,84532,421614] // Owner's approved subset.
}`}</Code><p>A null cctpFactoryAddress disables new native-USDC activation even when issuer routes are verified. Global config.token/paymentSymbol are compatibility fields; fund the actual selected card.token on its source chain. Never substitute an unverified asset or destination.</p><h3>Invoice identifies delivery</h3><p>PaymentInput.destinationChainId is optional and defaults to source chain. For Base use84532, for Arbitrum421614; CCTP domain 6/3 is not an EVM chain ID. The invoice buyer stays the X Layer vault address, while invoice.chainId and invoice.token identify the selected destination’s native USDC. Recipient, exact amount, freshness and approved origins must agree with the request.</p><Code title="Cross-chain payment with the SDK">{`const capabilities = await ig.capabilities();
const {card} = await ig.me();
const destinationChainId = 84532; // Only if owner-approved.
const network = capabilities.spendingNetworks.find(
  n => n.chainId === destinationChainId
);
if (!network || !card.settlement?.destinationChainIds.includes(destinationChainId))
  throw new Error("Owner did not approve this route");
// Ask the merchant for a fresh invoice:
// buyer=card.address, chainId=destinationChainId, token=network.token.
const queued = await ig.request({
  destinationChainId,
  recipient: "<APPROVED_MERCHANT_ADDRESS>",
  amount: "<EXACT_DECIMAL>",
  purchaseDescription: "<DELIVERABLE>",
  justification: "<MISSION_FIT>",
  category: "<PERMITTED_CATEGORY>",
  invoiceId: "<ACTUAL_MERCHANT_INVOICE_ID>",
  evidence: [{url:"https://<APPROVED_HOST>/invoice.json"}]
}, "<STABLE_OPERATION_KEY>");
// Poll queued.id. A deadline never authorizes another burn.`}</Code><p>Unsupported or unapproved routes fail before admission with HTTP422 DESTINATION_NOT_ALLOWED. Reference merchant admins provide chainId and token together for destination invoices. A partial pair returns INVOICE_ASSET_REQUIRED; an unsupported pair returns ASSET_OR_ROUTE_UNSUPPORTED. The agent key cannot issue merchant invoices.</p><h3>Permission, burn, attestation, mint</h3><ol><li>TapeOut checks and reserves the exact source funds and route.</li><li>GenLayer independently checks the destination invoice, committed evidence and owner’s mission. Only successful finalized approval permits release.</li><li>The vault rechecks TapeOut and burns native USDC through Circle CCTP V2. The signed route binds merchant, domain and amount.</li><li>The Actions worker fetches the existing burn’s Circle attestation and compares raw immutable fields with its source receipt.</li><li>Circle’s destination transmitter verifies its attestation. The worker independently verifies the exact message consumption and native-USDC mint to the merchant.</li><li>A receipt-attestor signature binds source hash, destination hash, message, request, route and amount. The X Layer vault acknowledges it before the request becomes PAID.</li></ol><Table heads={["State","What the agent should do"]} rows={[["BRIDGING","Source burn confirmed. Inspect sourceTxHash; never create a second burn."],["AWAITING_ATTESTATION","Wait for Circle standard finality. The same durable record is retried."],["MINTING","Attestation, destination receive/discovery or source acknowledgement pending."],["PAID","Exact destination mint and source acknowledgement verified. paymentTxHash is on the destination network."]]}/><p>bridge.phase is BURNED, ATTESTATION_PENDING, ATTESTED, MINT_SUBMITTED or CONFIRMED. The object includes source/destination chain and token, domain, amount and sourceTxHash. Optional messageHash, nonce, destinationTxHash and confirmationTxHash appear as observed. Missing receipts remain pending; no placeholder hash or fabricated reasoning is shown.</p><h3>Recovery after burn</h3><p>A burn is irreversible through owner controls. It consumes lifetime and original-period budget before delivery and keeps its invoice committed. Cancel, key revocation, pause, expiry or worker outage cannot cancel or repeat that burn. Signed transactions, attestation and message are stored durably before broadcast; Actions reconciles the same operation after restart.</p><p>Standard CCTP finality and runner scheduling can take minutes. Bounded SDK/MCP polling may end before delivery; keep the existing request ID and operation key. Missing destination gas, Circle/RPC errors and mismatched proof expose their actual asynchronous errorCode. Investigation resumes the same burn.</p><h3>Fees and trust boundaries</h3><p>Both supported USDC profiles use standard finality 2000, maxFee=0 and no hooks. It preserves the exact invoice amount; if Circle introduces a required source fee, new burns fail closed until fee-aware policy support exists. Relayer gas is separate. X Layer verifies the configured receipt-attestor signature and does not independently verify foreign-chain receipt consensus. Circle attestation verification and IntentGuard receipt-attestor/RPC trust are distinct boundaries.</p><h3>USDT0 availability</h3><p>USDT0 remains disabled on X Layer testnet. The supplied 0x779Ded0c9e1022225f8E0630b35a9b54bE713736 is an official chain 196 mainnet deployment and returned no code on chain 1952. The issuer deployment API returned no testnet entry. Testnet USDT0 remains unavailable until an official testnet deployment exists. In the separate verified mainnet profile, USDT0 settles locally on X Layer 196; it cannot use CCTP. No mock token or mainnet address is substituted into testnet.</p><p><a href="https://developers.circle.com/cctp/references/contract-addresses" target="_blank" rel="noreferrer">Circle CCTP deployments</a> · <a href="https://docs.usdt0.to/technical-documentation/deployments" target="_blank" rel="noreferrer">USDT0 issuer deployments</a></p></section>,
"credentials":<section id="credentials"><h2>Issue, rotate and revoke credentials</h2><p>In My agents → API key, issue a credential after the reviewer is ready. It appears once. Save it in a secret manager before closing. The server stores its hash; the browser keeps the revealed key only in component memory.</p><p>The key selects its own card. It permits /me, payment submission and that card’s request reads. It cannot choose another owner, withdraw tokens, change limits or enable a revoked vault.</p><p>Rotation invalidates the old credential and reveals a replacement once. Revocation blocks new requests. The worker cancels unburned, unpaid requests associated with invalidated keys. Existing CCTP burns remain durable and continue destination delivery; key revocation cannot reverse a burn. Confirmed payments remain. Pausing and key revocation are independent controls.</p><Code title="Key operations">{`POST /api/v1/owner/cards/<AGENT_ID>/keys
// Owner response: {"apiKey":"<ONE_TIME_SECRET>"}
DELETE /api/v1/owner/cards/<AGENT_ID>/keys
// Success: HTTP 204`}</Code></section>,
"agent-cards":<section id="agent-cards"><h2>Download and share an IntentGuard ATM card</h2><p>After activation, open your agent in My agents and choose Download card. The same public card is available in the agent explorer. It records the actual immutable identity and a timestamped snapshot of cumulative use.</p><Table heads={["Metric","Meaning"]} rows={[["requestCount","Actual admitted payment records for this agent. Identical HTTP retries do not add records."],["paidCount / fundsMoved","Delivered requests and exact PAID amounts in this agent’s asset across its approved spending networks. Approved/reserved amounts and pending burns are excluded."],["blockedCount / rejectedCount","Budget-gate denials and finalized semantic rejections."],["needsEvidenceCount / cancelledCount / activeCount","Evidence-required, cancelled and currently active records."],["chainId / token / asOf","Source-vault asset/chain and snapshot time. Each bridge records its destination; live balances are separate."]]}/><Code title="Public card endpoints">{`GET /api/v1/explorer/agents/<AGENT_ID>/card
// {agent,usage,shareUrl}
GET /api/v1/explorer/agents/<AGENT_ID>/card.svg
// image/svg+xml attachment; no authentication required`}</Code><p>Download SVG for scalable use or PNG for social sharing. Share on X opens a composer with the public agent link; attach the downloaded image manually. A URL intent cannot upload image bytes. The card excludes keys, cookies, invoice content and private justification. It is a public identity snapshot, not an NFT, a credential or permission to spend.</p><p>If chain reads fail, live balances show Unavailable. Cumulative totals still describe stored real usage, never estimated or fabricated activity. Refresh/download again to update the snapshot.</p></section>,
"agent-api":<section id="agent-api"><h2>Connect an agent with the SDK or curl</h2><p>Use the SDK source in this repository or call the HTTP API. These examples contain explicit placeholders. Replace them with the actual vault, merchant invoice, evidence and saved key; examples are never displayed as activity records.</p><Code title="TypeScript SDK">{`import { IntentGuard } from "./packages/sdk/index";
const ig = new IntentGuard({
  baseUrl: "https://intentguard-tapeout.vercel.app",
  paymentEnvironment: "testnet",
  apiKey: process.env.INTENTGUARD_API_KEY!
});
const capabilities = await ig.capabilities();
const { card } = await ig.me();
// For cross-chain USDC: check card.settlement, get a destination
// invoice and supply its owner-approved destinationChainId.
const queued = await ig.request({
  recipient: "<APPROVED_MERCHANT_EVM_ADDRESS>",
  amount: "1.000001",
  category: "<PERMITTED_CATEGORY>",
  purchaseDescription: "<PURCHASE_DESCRIPTION>",
  justification: "<WHY_THIS_SERVES_THE_MISSION>",
  invoiceId: "<MERCHANT_INVOICE_ID>",
  evidence: [{ url: "https://<APPROVED_HOST>/invoice.json" }]
}, "<STABLE_UNIQUE_OPERATION_KEY>");
const result = await ig.wait(queued.id, {
  timeoutMs: 600_000, intervalMs: 5_000
});
if (result.status === "PAID") console.log(result.paymentTxHash);
// On timeout, resume polling queued.id. Do not create a duplicate.`}</Code><Code title="curl payment request">{`curl "https://intentguard-tapeout.vercel.app/api/v1/requests" \\
  -H "Authorization: Bearer <AGENT_API_KEY>" \\
  -H "Content-Type: application/json" \\
  -H "Idempotency-Key: <STABLE_UNIQUE_OPERATION_KEY>" \\
  --data '{
    "recipient":"<APPROVED_MERCHANT_EVM_ADDRESS>",
    "amount":"1.000001",
    "category":"<PERMITTED_CATEGORY>",
    "purchaseDescription":"<PURCHASE_DESCRIPTION>",
    "justification":"<MISSION_JUSTIFICATION>",
    "invoiceId":"<MERCHANT_INVOICE_ID>",
    "evidence":[{"url":"https://<APPROVED_HOST>/invoice.json"}]
  }'
curl "https://intentguard-tapeout.vercel.app/api/v1/requests/<REQUEST_ID>" \\
  -H "Authorization: Bearer <AGENT_API_KEY>" \
  -H "X-IntentGuard-Environment: testnet"`}</Code><p>Optional destinationChainId selects an owner-approved spending network; omission defaults to source. Invoice token/chain must match delivery. SDK capabilities() exposes assets, spendingNetworks and cctpFactoryAddress; /me identifies the actual card token. SDK wait() treats BRIDGING, AWAITING_ATTESTATION and MINTING as pending and returns terminal PAID, BLOCKED, REJECTED, NEEDS_EVIDENCE, EXPIRED or CANCELLED. Inspect status. HTTP 202 confirms admission to the queue, not payment completion.</p></section>,
"mcp-skills":<section id="mcp-skills"><h2>Install the agent skill and MCP</h2><p>The repository includes a self-contained agent skill and an MCP server with bundled protocol instructions and OpenAPI. An agent can understand the protocol without a documentation URL. Both preserve the owner mandate and keep credentials outside tool arguments.</p><Code title="Install the skill">{`npx skills add TS-mfon/intentguard --skill intentguard`}</Code><Code title="Run the MCP from source">{`git clone https://github.com/TS-mfon/intentguard.git
cd intentguard
npm ci --ignore-scripts --prefix packages/mcp
export INTENTGUARD_BASE_URL=https://intentguard-tapeout.vercel.app
export INTENTGUARD_PAYMENT_ENV=testnet
# Supply INTENTGUARD_API_KEY through your client's secure environment.
node packages/mcp/src/cli.mjs`}</Code><p>The private source package is not published to npm. Use the checked-out executable, not npx @intentguard/mcp.</p><Code title="MCP client configuration">{`{
  "mcpServers": {
    "intentguard": {
      "command": "node",
      "args": ["/absolute/path/intentguard/packages/mcp/src/cli.mjs"],
      "env": {
        "INTENTGUARD_BASE_URL": "https://intentguard-tapeout.vercel.app",
        "INTENTGUARD_PAYMENT_ENV": "testnet",
        "INTENTGUARD_API_KEY": "<OWNER_ISSUED_SECRET>"
      }
    }
  }
}`}</Code><p>Keep that secret-bearing configuration out of Git. Set both the API origin and payment environment explicitly. The SDK and MCP read public configuration before sending credentials, then verify the credential-bound card before payment. Mainnet clients also verify the source and release identity. HTTPS is required outside loopback development. Public tools work without a key.</p><Table heads={["Capability","Use"]} rows={[["intentguard://protocol","Read the bundled integration manual before payment."],["intentguard://openapi","Read complete HTTP schemas."],["payment_integration(task)","Plan integration from the mandate and resources."],["get_config / get_my_agent","Confirm runtime and credential-bound policy/balances."],["submit_payment","Admit one invoice-backed request with stable idempotency."],["get_payment / wait_for_payment","Read or poll the same operation. Wait is bounded to 45 seconds."],["list_agents / list_transactions","Read actual public records with pagination."],["get_transaction / get_agent_card","Read verified reasoning, review stage or real ATM-card statistics."]]}/><p>Tool success returns structured <code>{"{ok:true,status,data}"}</code>. Failure sets isError with <code>{"{ok:false,error:{code,message,status,retryable,requestId?,retryAfterSeconds?}}"}</code>. Payment submission never silently retries. Bounded waiting returns pending with the same operationId; resume polling rather than creating another payment.</p><p><a href="https://github.com/TS-mfon/intentguard/blob/main/docs/PROTOCOL.md" target="_blank" rel="noreferrer">Complete portable protocol manual ↗</a> · <a href="/llms.txt">Agent resource index</a></p></section>,
"api-reference":<section id="api-reference"><h2>HTTP API reference</h2><p>Paths below are relative to /api/v1. JSON bodies use Content-Type: application/json. Send X-IntentGuard-Environment for the selected profile. Agent calls use Authorization: Bearer &lt;AGENT_API_KEY&gt;. Same-origin owner calls use the signed-session cookie; separate-origin calls use Authorization: Owner &lt;SESSION&gt;. Owner mutations require the approved frontend Origin. Public requests carry no credential.</p><Table heads={["Method and path","Access / result"]} rows={[["GET /explorer/agents/{id}/card","Public. {agent,usage,shareUrl}; real admitted-request counts and PAID funds only."],["GET /explorer/agents/{id}/card.svg","Public downloadable image/svg+xml snapshot."],["GET /config","Public payment/review/API/frontend identity, release/source, verified assets/routes, settlementVersion and readinessReasons."],["GET /health","Public deployment identity, database reachability and worker freshness; unavailable dependencies return 503."],["POST /auth/challenge","Public. {address} → {message}; single-use challenge."],["POST /auth/login","Public. {address,signature} → same-origin cookie or {ownerSession,expiresAt} for the approved separate frontend."],["GET /auth/session","Public. {address:string|null}."],["POST /auth/logout","Clear owner session."],["POST /owner/drafts","Owner. {description,guidance?} → 202 {id,status}."],["GET /owner/drafts/{id}","Owner-isolated typed terms, clarification and activation config."],["GET /owner/cards","Owner. {cards:CardView[]} with actual balances and reviewer."],["POST /owner/cards","Owner. {draftId,cardAddress,activationTx}; verifies deployed config."],["POST /owner/cards/{id}/reviewer","Owner. Retry a failed reviewer → 202; preserves vault and policy. Concurrent or unnecessary retries return 409."],["GET /owner/cards/{id}/replacement","Owner. Read the original vault, pending work and accounting warnings."],["POST /owner/cards/{id}/replacement","Owner. {settlement,acknowledgeAccountingReset:true} → policy-copy draft; original funds and history stay intact."],["POST /owner/cards/{id}/keys","Owner. Issue or rotate → {apiKey}, reveal once."],["DELETE /owner/cards/{id}/keys","Owner. Revoke → 204."],["GET /owner/requests","Owner. {requests:RequestView[]}."],["GET /owner/requests/{id}","Owner. Actual request detail."],["GET /me","Agent bearer. {card:CardView} for bound vault."],["POST /requests","Agent bearer + Idempotency-Key. PaymentInput → 202 {id,status}."],["GET /requests/{id}","Agent bearer. RequestView for its own card."],["GET /explorer/agents","Public. {agents,nextCursor}; bounded limit and cursor pagination."],["GET /explorer/transactions","Public. {transactions,nextCursor}; limit, status, agentId and cursor."],["GET /explorer/transactions/{id}","Public. {transaction,agent,reasoningSource}; verified review only."],["GET /explorer/transactions/{id}/proof","Public captured CCTP receipt bundle and canonical proofHash. Independently verify receipts and deployment identity."],["POST /demo/invoices","Configured testnet merchant. Separate merchant administrator bearer credential; agent keys cannot issue invoices."],["GET /demo/invoices/{id}","Public configured testnet invoice after actual issuance."]]}/><h3>PaymentInput fields</h3><Table heads={["Field","Constraint"]} rows={[["recipient","Approved EVM address."],["amount","Positive exact decimal string, at most six fractional digits."],["purchaseDescription","3–2,000 characters."],["justification","3–6,000 characters explaining mission fit; omitted from public views."],["category","1–200 characters; checked against policy."],["invoiceId","1–200 characters; merchant-issued invoice ID."],["evidence","1–8 unique public HTTPS URLs with optional sha256 hex64 pin."]]}/><p>RequestView contains id, cardId, cardName, status, original request, requestHash, evidenceHash, guard, review, chain transaction hashes, error and createdAt/updatedAt in Unix milliseconds and reviewStage. Public views omit private justification, sessions, credentials and signed transaction bytes.</p><h3>Admission response and polling</h3><p>POST /requests returns HTTP 202 with an operation id and its current status, including on an identical retry that is already PAID. Preserve that id and GET /requests/id with the same agent key. The GET returns the full RequestView; paymentTxHash identifies the X Layer transfer after PAID. genLayerTxHash identifies the separate review. A transaction hash or APPROVED status alone does not confirm fund delivery.</p><h3>Rate limits</h3><p>Agent requests share 60 calls per fixed UTC minute for each active credential, including GET polling and POST submissions. Owner routes allow 120 calls per minute per owner, and login challenges allow 10 per minute per address. HTTP 429 returns RATE_LIMIT and instructs you to retry next minute. Successful authenticated responses expose RateLimit-Limit, RateLimit-Remaining, RateLimit-Reset and RateLimit-Policy. A 429 includes Retry-After until the next fixed minute. Poll every five seconds, avoid competing polling loops, and preserve the operation key when retrying.</p><p>Transport bodies are bounded to 32 KiB, canonical payment input to 14 KiB, draft input to 16 KiB, each source to 64 KiB UTF-8, and the evidence bundle to 128 KiB. URLs are at most 2,048 characters.</p></section>,
"statuses":<section id="statuses"><h2>Statuses and errors</h2><Table heads={["Status","Meaning / next action"]} rows={[["QUEUED","Admitted for worker processing."],["RESERVED","Exact amount reserved by onchain guard."],["REVIEWING","Evidence review in progress."],["AWAITING_FINALITY","Submitted GenLayer call awaits verified successful finality."],["APPROVED","Finalized approval; delivery still pending."],["BRIDGING","Source USDC burned; destination delivery pending."],["AWAITING_ATTESTATION","Existing burn awaits Circle standard-transfer finality."],["MINTING","Destination mint discovery/submission or vault acknowledgement pending."],["PAID","Direct delivery or exact destination mint plus source acknowledgement verified."],["BLOCKED","Financial, recipient, asset, enabled or validity guard denied."],["REJECTED","Finalized review rejected purchase; reservation cancelled."],["NEEDS_EVIDENCE","Evidence insufficient or inaccessible; inspect and repair."],["EXPIRED","Authorization or reservation expired."],["CANCELLED","Owner or gateway cancelled request."],["RETRYING","Recoverable worker error; durable request continues."]]}/><p>Review decisions are APPROVE, REJECT and NEEDS_EVIDENCE. They are separate from payment statuses; the public rejection status is REJECTED. Criteria return PASS, FAIL or INSUFFICIENT.</p><Code title="Error response">{`{"error":{"code":"<MACHINE_CODE>","message":"<ACTIONABLE_REASON>","retryable":false,"requestId":"<CORRELATION_ID>","details":[{"field":"amount","code":"custom","message":"<VALIDATION_REASON>"}]}}`}</Code><Table heads={["HTTP","Handling"]} rows={[["400","INVALID_JSON: supply valid JSON, including a body when required."],["405","METHOD_NOT_ALLOWED: use the documented method; inspect Allow."],["415","UNSUPPORTED_MEDIA_TYPE: use Content-Type: application/json."],["401","Missing, expired or invalid session/key. Reauthenticate or rotate."],["403","Wrong owner/card or illegitimate origin. Preserve the actual permission error."],["404","Record unavailable or outside caller access."],["409","Conflict: changed idempotent payload or registration mismatch."],["413","Body exceeds transport bound."],["422","Invalid schema/asset/route: inspect DESTINATION_NOT_ALLOWED, ASSET_OR_ROUTE_UNSUPPORTED or INVOICE_ASSET_REQUIRED and field details."],["429","Rate limit. Back off with the same operation key."],["503","Service/dependency unavailable; BRIDGE_NOT_CONFIGURED means native-USDC factory unavailable. Retry the same operation."]]}/><h3>Review stages and terminal handling</h3><p>reviewStage is PENDING, COMPLETE, SKIPPED or FAILED with a reason. BLOCKED before review and NEEDS_EVIDENCE from preflight are SKIPPED. A terminal consensus/VM failure is FAILED. Terminal states never show a pending review. The error retryable flag and HTTP transport code do not change the terminal payment outcome.</p><p>Every response includes X-Request-Id. Error responses are no-store. Preserve the correlation ID when reporting a failure. Retry-After is provided only when retry is appropriate; unchanged invalid input and final rejection require correction.</p></section>,
"idempotency":<section id="idempotency"><h2>Idempotency, retries and invoice replay</h2><p>POST /requests requires Idempotency-Key. Preserve one stable unique key per business operation across transport retries. Admission uses a card-scoped SHA256 commitment. The same key with identical input returns the same admitted operation; changed input conflicts.</p><p>If a response is lost or SDK wait times out, read the existing request or resend identical input with the same key. A new key is another attempted operation. The vault also commits lowercase recipient plus invoiceId, preventing duplicate pending or paid invoices.</p><p>Signed bytes are persisted before broadcast. Runner restarts resume the same transaction and reconcile chain state. Cancellation or expiry releases immutable reservations. Repairing evidence may need a new merchant invoice and new operation after the old request is terminal.</p></section>,
"invoice":<section id="invoice"><h2>Merchant invoice schema</h2><p>Merchant invoices establish buyer, recipient, token, chain and exact amount. The buyer must be the agent vault, not the owner wallet. All fields must agree with the committed request and policy.</p><Code title="Merchant invoice JSON">{`{
  "invoiceId": "<MERCHANT_INVOICE_ID>",
  "buyer": "<AGENT_VAULT_EVM_ADDRESS>",
  "token": "<ACTUAL_DELIVERY_TOKEN>",
  "chainId": 1952,
  "recipient": "<APPROVED_MERCHANT_EVM_ADDRESS>",
  "amount": "1.000001",
  "description": "<PURCHASE_DESCRIPTION>",
  "issuedAt": <UNIX_SECONDS>,
  "expiresAt": <UNIX_SECONDS>
}`}</Code><p>Serve accessible UTF-8 JSON/text from an approved merchant HTTPS origin. Supporting proof uses approved evidence origins. Expiry is capped by the invoice, policy lifetime and authorization’s 24-hour maximum. Before reservation, missing, stale or mismatched invoice fields and digest mismatches produce NEEDS_EVIDENCE. A finalized semantic review can instead return REJECT or NEEDS_EVIDENCE; inspect the actual decision and criteria.</p><h3>Obtain an invoice</h3><p>Ask the approved merchant to issue a fresh invoice for the agent vault. The agent API key authorizes payment requests and request reads; it cannot issue invoices on behalf of a merchant. The configured testnet reference merchant uses a separate administrator credential held by its operator. For CCTP requests, buyer remains the X Layer vault while invoice chainId/token identify destination USDC. POST /demo/invoices accepts buyer (vault address), amount (exact decimal string), description (3–1,000 characters), and optional paired chainId/token, and returns HTTP 201 with <code>invoice</code> and <code>url</code>. Provide chainId/token together for official native-USDC delivery or omit both for legacy invoices. A partial pair returns INVOICE_ASSET_REQUIRED; unsupported asset/route returns ASSET_OR_ROUTE_UNSUPPORTED. Use that returned invoiceId and url in the payment request. Never send a merchant administrator credential to an agent.</p><p>Keep bytes stable during review. GenLayer refetches and compares SHA256 against the snapshot. Origins and hashes verify provenance and integrity, not the truth of claims outside merchant sources.</p></section>,
"snapshots":<section id="snapshots"><h2>Snapshots, hashes and commitments</h2><p>Financial preflight precedes evidence retrieval. The API pins public DNS, rejects private destinations, credentials, redirects and non-text responses, and bounds source/bundle size. Optional SHA256 pins must match fetched content.</p><Code title="Canonical commitments">{`Snapshot = { url, sha256, content, fetchedAt }
evidenceHash = SHA256(canonical(snapshotBundle))
CanonicalRequest = {
  ...PaymentInput, cardId, cardAddress, owner, policyHash,
  token, chainId, amountAtomic, evidenceHash, expiresAt,
  // Native USDC only:
  settlementHash, destinationChainId, destinationToken, destinationDomain
}
requestHash = SHA256(canonical(CanonicalRequest))
policyHash = SHA256(canonical(Policy))`}</Code><p>Canonical JSON recursively sorts keys, keeps array order, uses compact UTF-8 and preserves amount strings. Settlement destinations are sorted before their SHA256 commitment; the V3 reviewer validates the committed destination chain/token/domain. Digests are 0x-prefixed SHA256. Review results must match the exact policy, request and evidence.</p><p>Every criterion appears once, and sources must refer to verified submitted evidence. PASS without a citation is invalid. Transaction details expose the actual commitments and verified reasoning without private owner input or signing bytes.</p></section>,
"reasoning":<section id="reasoning"><h2>GenLayer reasoning and finality</h2><p>PermissionInterpreter proposes terms from owner input. Per-agent PurchaseReviewer evaluates committed requests against immutable policy. The worker verifies the expected source contract, operator, target method and arguments.</p><p>A receipt alone is insufficient: approval requires successful FINALIZED VM execution, consensus agreement and matching policy/request/evidence hashes. Every criterion must PASS. Small requests receive the same semantic review.</p><p>Public details display overall reason, criterion statuses/reasons and source citations only with reasoningSource genlayer-finalized-contract. Genuinely active reviews are Pending; pre-review denials are Skipped; terminal review failures are Failed. Unavailable means the stored result could not be independently verified at this read. Review and X Layer payment have separate transactions.</p><p>Finality may require several Actions runs. Pending details poll every five seconds online. Slow consensus or schedule delay does not itself mean rejection.</p><h3>Consensus limits</h3><p>GenLayer uses Optimistic Democracy with validators and potential appeals. Network and round configuration determine participation; IntentGuard does not promise exactly five independent LLMs. Consensus reduces single-model error but does not make hallucination impossible. The X Layer vault relies on its configured attestor for the foreign-chain result.</p><p>The real 12-request audit observed safe cancellation rather than committed rejection in two semantic cases. See the published audit and current release evidence; a build passing does not by itself prove semantic reliability.</p></section>,
"architecture":<section id="architecture"><h2>Architecture and trust boundaries</h2><p>Vercel serves the frontend and API. MongoDB holds agents, hashed keys, jobs, snapshots and transaction journals. Actions runs the worker. X Layer holds funded vaults and the numeric evaluator; GenLayer runs proposal/evidence consensus.</p><ol><li>Owner signs finalized immutable terms into the vault factory configuration.</li><li>API admits card-bound input and checks numerical feasibility.</li><li>Gateway reserves the exact amount through the NAND guard.</li><li>Reviewer refetches proof and produces a finalized committed decision.</li><li>Attestor validates it and signs EIP712 release.</li><li>Vault rechecks constraints and transfers the stored amount once.</li></ol><h3>Circuit and release</h3><p>The testnet adapter runs unchanged TapeOut NetlistVM with the generated NAND netlist. Exact 64-bit comparisons enforce payment, lifetime, period, time, recipient, asset and enabled checks. Beacon implementation and netlist pins fail closed on mismatch.</p><Code title="Legacy-card EIP712 release">{`Domain = {
  name: "IntentGuard", version: "1",
  chainId: 1952, verifyingContract: "<AGENT_VAULT>"
}
Release = {
  requestId: bytes32, requestHash: bytes32, policyHash: bytes32,
  evidenceHash: bytes32, decisionHash: bytes32,
  genLayerTxHash: bytes32, validUntil: uint64
}`}</Code><p>Legacy native-USDC reviewers use source version 3. New version-2 settlement profiles require reviewer version 4, which binds the payment environment, token, policy, request, evidence and destination permission while running on Studionet testnet. Existing version 2 and version 1 source pins are preserved. Version2 reviewers use deterministic preflight. Deterministic permission failures and missing proof are evaluated before model output and independently reproduced by validators without an LLM. Semantic approvals still require model validation. Existing version 1 reviewers keep their pinned source and legacy audit limitations.</p><p>X Layer verifies the attestor signature for GenLayer approval and, for CCTP cards, the receipt attestor’s destination-mint acknowledgement. It does not verify foreign-chain consensus directly. A compromised attestor could attest false semantic approval within financial and merchant restrictions. A compromised gateway can reserve permitted funds and delay work but cannot independently sign release.</p><p>Keys cannot withdraw or edit terms. Owner withdrawals remain independent of evaluator availability. For changed terms or a legacy reviewer, open My agents → Policy → Prepare owner replacement. A policy-copy draft requires explicit acknowledgement that lifetime and period accounting starts at zero; old reservations, funds and history stay in the original vault. Merchant evidence establishes origin/integrity, so choose sources whose claims you trust. This testnet adapter is not an official TapeOut registry deployment or an audit claim.</p></section>,
"owner-controls":<section id="owner-controls"><h2>Owner controls</h2><Table heads={["Control","Effect"]} rows={[["Fund vault","Token transfer; immutable budgets stay fixed."],["Pause / Resume","Owner setEnabled(false/true) within current terms."],["Revoke","Permanent disable; cannot resume."],["Withdraw","Only unreserved funds return to owner; contract rechecks."],["Cancel request","Cancels an unpaid/unburned reservation. An existing CCTP burn cannot be cancelled."],["Issue / Rotate / Revoke key","Invalidated unpaid/unburned requests are cancelled. Existing burns continue delivery."],["Replace policy","Create a new vault; existing policy is immutable."]]}/><p>Revoked vaults can return unreserved funds. Cancel or expire reservations before withdrawing their tokens. PAID requests and existing CCTP burns cannot be cancelled or refunded by this control.</p></section>,
"contracts":<section id="contracts"><h2>Deployed testnet contracts</h2><p>X Layer Testnet: chain 1952, https://testrpc.xlayer.tech. GenLayer Studionet: chain 61999, https://studio.genlayer.com/api. Runtime config identifies the connected deployment.</p><div className="docs-address-list">{[
["NAND processor","0xa34d101011d4dbe18375ff2e7591b646e22c2ff3","https://www.oklink.com/xlayer-test/address/0xa34d101011d4dbe18375ff2e7591b646e22c2ff3"],
["Immutable beacon","0x699f57090c5c74acc3b7f7f2fdc4f808ff6a010f","https://www.oklink.com/xlayer-test/address/0x699f57090c5c74acc3b7f7f2fdc4f808ff6a010f"],
["TEST-USDT","0x47f846c659b4df565d2e8b1cd32f610e68d11b9a","https://www.oklink.com/xlayer-test/address/0x47f846c659b4df565d2e8b1cd32f610e68d11b9a"],
["Vault factory","0xb452f9fabdf1599b2c72acbad0fc52baac58dfb7","https://www.oklink.com/xlayer-test/address/0xb452f9fabdf1599b2c72acbad0fc52baac58dfb7"],
["GenLayer interpreter","0x0922B814Cd91a9f2fF36F95D321A74eA22CEa9d3","https://explorer-studio.genlayer.com/address/0x0922B814Cd91a9f2fF36F95D321A74eA22CEa9d3"]
].map(([name,address,url])=><div key={address}><strong>{name}</strong><code>{address}</code><a href={url} target="_blank" rel="noreferrer">View contract ↗</a></div>)}</div><p>Each agent’s actual vault and reviewer appear in My agents. Signing keys are Actions secrets, outside frontend bundles and Vercel public config.</p></section>,
"actions":<section id="actions"><h2>GitHub Actions worker and latency</h2><p>New proposals, activated agents and payment requests automatically wake the Actions worker after their jobs are stored. Pending authenticated reads can retry the trigger. Each run processes a 180-second burst and starts another run when work remains. A scheduled workflow provides fallback recovery; GitHub runner availability and GenLayer consensus still affect latency.</p><p>Workflow concurrency serializes runners; MongoDB’s global worker lease is authoritative for signing. Job leases fence completion. Fair queue rotation prevents proposal work from starving payments. Continuous processing/finality delays exceeding 30 minutes become PROCESSING_TIMEOUT: setup becomes FAILED, and unburned payment cancellation stays active until its reservation is released. Existing CCTP burns remain active until destination delivery is reconciled; processing deadlines cannot create a second burn or false cancellation. Commitments and signed transaction bytes stay in MongoDB, so subsequent runs resume finality and transfers.</p><Code title="Worker operations">{`gh workflow run worker.yml -f duration_seconds=180
gh run list --workflow worker.yml
gh run view <RUN_ID> --log
pnpm exec tsx apps/worker/main.ts --duration-seconds 180`}</Code><p>Repository secrets: MONGODB_URI, XLAYER_OPERATOR_PRIVATE_KEY, REVIEW_ATTESTOR_PRIVATE_KEY, GENLAYER_OPERATOR_PRIVATE_KEY. Public variables include chains, RPCs, token, factory, gateway/attestor, processor/circuit/beacon pins, interpreter, database and APP_URL. The workflow refuses mainnet signing. Vercel uses a server-only GitHub Actions credential to trigger runs; signing keys stay in Actions. Concurrent triggers share a durable lease and reuse healthy active runs.</p><p>Three consecutive connectivity/storage errors fail a run visibly. Interruptions stop new claims and retain recovery state. WORKER_RUN_COMPLETED proves a completed burst; a real purchase still requires guard, finalized review and transfer evidence.</p></section>,
"troubleshooting":<section id="troubleshooting"><h2>Troubleshooting</h2><Table heads={["Symptom","Recovery"]} rows={[["Wallet declined","Retry; form and draftId are preserved. Confirm account/network."],["Origin or permission denied","Use the actual app URL and a fresh session challenge. API errors remain distinct from wallet rejection."],["Expired session","Sign in as the same owner; saved form and draftId resume."],["Wrong network / gas failure","Owner operations use the configured X Layer source chain: 1952 testnet or 196 mainnet, with native OKB gas. Destination relaying needs gas on the actual destination network; source tokens and gas are separate."],["Reviewer pending","Keep My agents open; pending reads automatically wake Actions. Credential issuance waits for verified successful GenLayer reviewer finality."],["Proposal or reviewer failed","Failed proposals require revised instructions and a new proposal. For a failed reviewer, choose Retry reviewer initialization in My agents."],["Review failed","The worker cancels its reservation; no payout is authorized from a failed GenLayer review."],["Confirmed activation, failed registration","Retry the same draft’s activation recovery using the saved public receipt."],["Funds unavailable","Inspect actual balance, reservations, lifetime/period limits. Failed reads show errors, not fabricated zeros."],["Pending request","Check Actions and GenLayer; poll the same ID through minute-scale processing."],["BLOCKED","Inspect exact financial, time, recipient, asset, enabled and pin failures."],["REJECTED / NEEDS_EVIDENCE","Read actual reasons; verify invoice fields, freshness, URLs and stable bytes."],["Hash mismatch","Serve stable exact content matching optional pins and snapshot."],["Withdrawal fails","Cancel/expire unburned reservations; only unreserved funds are withdrawable. Existing CCTP burns have left the source vault and continue delivery."],["CCTP waiting","Inspect source burn, attestation, destination mint and vault acknowledgement. Keep the same ID; never burn again to recover. Check Actions, Circle/RPC and destination gas."],["USDT0 unavailable","USDT0 is enabled only for verified X Layer mainnet local settlement. It is unavailable on testnet 1952 and cannot use USDC CCTP routes."],["Service offline","Reconnect or retry. Empty means no real records; error means records could not be fetched."]]}/></section>,
"faq":<section id="faq"><h2>Frequently asked questions</h2><p>Start by identifying which layer failed: HTTP admission, financial preflight, invoice capture, GenLayer finality or X Layer settlement. These layers have different recovery actions. Keep the operation ID, original Idempotency-Key and request correlation ID while investigating. A successful API call or a GenLayer hash does not mean a merchant received funds.</p><p>If the operation is still active, poll its existing ID and inspect Actions plus the relevant chain transaction. If it is terminal, stop waiting and diagnose the actual guard failure, criterion result or evidence error. Correcting a purchase is a new business operation; repeating an unchanged rejected payload cannot change its outcome. The answers below explain the boundaries that commonly cause integration friction.</p>{[
["Can an agent spend directly from my wallet?","No. Its bearer key selects one separate funded vault. It can ask for a constrained payment but cannot sign arbitrary transactions, choose another vault, change policy or withdraw. Owner-wallet assets outside the vault are not controlled by that credential."],
["Does APPROVED mean the merchant received tokens?","No. APPROVED records verified finalized semantic approval while X Layer settlement is still pending. Wait for PAID and inspect paymentTxHash. A broadcast hash, HTTP 202 or successful GenLayer receipt alone does not establish token delivery."],
["Can I edit terms after activation?","No. Budgets, recipients, policy hash and review criteria are immutable. Create and activate a replacement agent vault for changed terms. Adding tokens increases the physical balance but never increases lifetime spending permission."],
["Why reserve before review?","Pending requests must consume physical funds and lifetime/original-period budgets before asynchronous review. Otherwise concurrent approved requests could collectively overspend. Cancellation or expiry releases the exact reservation; a paid request consumes its original period."],
["Why are there no transactions?","The product only displays actual admitted payment operations. A new agent has no history until used. Filters can hide records; clear them or inspect the owner ledger. An explicit fetch error means data could not be read, while an empty state means no matching records were returned."],
["What if a POST response is lost or polling times out?","Reuse identical input and the SAME Idempotency-Key to recover the existing operation. Once its ID is known, poll that ID. A new key is another attempted purchase, not a safe transport retry. Bounded polling ending does not cancel or duplicate the persisted request."],
["What if Actions stops?","Jobs, leases, commitments and signed transaction journals remain in MongoDB. A later run reconciles the same operation after leases expire. Pending reads request a worker wake and the schedule is a fallback. Runner startup, storage/RPC outages and GenLayer finality can still delay work."],
["How do I recover a failed reviewer?","Only a terminal FAILED initialization enables the owner-only retry action in My agents. It deploys and verifies a replacement reviewer for the same immutable policy and vault, with its own attempt journal. Funding does not fix reviewer failure, and issuing another key while it is unready cannot bypass readiness."],
["Why does a blocked transaction say Review skipped?","A failed numerical, recipient, asset, enabled or time guard prevents semantic review. There is no model result to wait for. Skipped describes a stage that was not run; Failed describes an attempted review that ended without a successful finalized result."],
["Does GenLayer remove attestor trust or make hallucination impossible?","No. Optimistic Democracy validates model output through consensus and possible appeals, reducing dependence on one result. Participation varies by network/round and model errors can remain. X Layer verifies the attestor's EIP-712 signature for the foreign-chain decision and independently enforces numerical constraints."],
["What happens to an old policy after the site URL changes?","Its merchant/evidence origins remain immutable. The new canonical UI URL does not rewrite them. Existing approved invoice-source origins are preserved for compatibility; a human must create a new policy to approve different sources."],
["Are these mainnet assets or a bank ATM card?","The environment label identifies whether payments use testnet or mainnet assets. Testnet 1952 tokens have no monetary value. Verified mainnet 196 supports USDC and local USDT0 with Studionet testnet review. Existing testnet cards retain their immutable tokens. The downloaded card is a public identity/use snapshot, not a bank card, NFT, API credential or proof of current solvency."],
["Can I recover a revealed key?","No. The server stores its hash, and the UI reveals the secret once. Save it in a secret manager. Rotate a lost key; old credentials become invalid. Unburned/unpaid requests are cancelled, while existing CCTP burns continue destination recovery. Never attach a key to an X post or downloaded card."],
["How are citations and untrusted text displayed?","Reasons are plain text. The public detail independently verifies the successful finalized contract result and commitments before showing reasoning. Only HTTP/HTTPS links can be opened. Evidence text, including embedded instructions, remains untrusted data rather than agent instructions."],
["Can an agent learn the protocol without visiting the docs?","Yes. Install the repository intentguard skill or configure the bundled MCP server. Both contain the portable protocol reference; MCP also exposes OpenAPI through intentguard://openapi. Inspect the actual runtime and credential-bound policy before making a payment."]
].map(([q,a])=><details key={q}><summary>{q}</summary><p>{a}</p></details>)}</section>
};
export function Docs({section="quickstart"}:{section?:DocsSection}){
 const index=docsSections.findIndex(([,id])=>id===section),current=docsSections[index],previous=docsSections[index-1],next=docsSections[index+1];
 return <main id="main" className="container page"><div className="page-heading docs-section-header"><p className="eyebrow">PROTOCOL DOCUMENTATION</p><h1>{current[2]}</h1><p>One section at a time. Exact integration rules, actual states and explicit trust boundaries.</p></div><div className="docs-network"><NetworkStrip/></div><details className="docs-mobile-toc"><summary>Documentation sections</summary><Toc section={section}/></details><div className="docs-layout"><aside className="docs-toc"><Toc section={section}/></aside><article className="docs-article">{content[section]}<nav className="docs-section-nav" aria-label="Adjacent documentation sections">{previous?<Link href={"/docs/"+previous[1]}>← {previous[2]}</Link>:<span/>}{next?<Link href={"/docs/"+next[1]}>{next[2]} →</Link>:<Link href="/agent-setup">Create an agent →</Link>}</nav></article></div></main>
}
